CREATE TABLE public.user_roles (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('owner','admin','member')), active boolean NOT NULL DEFAULT true, can_invite boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role; ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX vault_single_owner ON public.user_roles(role) WHERE role='owner';
CREATE TABLE public.testing_invitations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL, token_hash text UNIQUE NOT NULL, role text NOT NULL CHECK(role IN ('admin','member')), created_by uuid NOT NULL REFERENCES public.profiles(id), expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), accepted_at timestamptz, revoked_at timestamptz);
GRANT SELECT ON public.testing_invitations TO authenticated; GRANT ALL ON public.testing_invitations TO service_role; ALTER TABLE public.testing_invitations ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.testing_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid, event text NOT NULL, subject_id uuid, occurred_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.testing_audit TO authenticated; GRANT ALL ON public.testing_audit TO service_role; ALTER TABLE public.testing_audit ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.test_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id) ON DELETE CASCADE, label text NOT NULL CHECK(label IN ('desktop-check','phone-check','tablet-check')), created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,DELETE ON public.test_records TO authenticated; GRANT ALL ON public.test_records TO service_role; ALTER TABLE public.test_records ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.testing_member() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND active) $$; REVOKE ALL ON FUNCTION public.testing_member() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.testing_member() TO authenticated;
CREATE OR REPLACE FUNCTION public.account_session_active() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT public.testing_member() AND EXISTS(SELECT 1 FROM public.account_sessions s WHERE s.id=nullif(auth.jwt()->>'session_id','')::uuid AND s.user_id=auth.uid() AND s.revoked_at IS NULL AND s.expires_at>now()) $$;
CREATE FUNCTION public.testing_owner() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT public.account_session_active() AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='owner' AND active) $$; REVOKE ALL ON FUNCTION public.testing_owner() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.testing_owner() TO authenticated;
CREATE FUNCTION public.testing_inviter() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT public.account_session_active() AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND active AND (role='owner' OR can_invite)) $$; REVOKE ALL ON FUNCTION public.testing_inviter() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.testing_inviter() TO authenticated;
CREATE POLICY roles_self ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.testing_owner());
CREATE POLICY invites_admin ON public.testing_invitations FOR SELECT TO authenticated USING(public.testing_owner() OR (created_by=auth.uid() AND public.testing_inviter()));
CREATE POLICY audit_owner ON public.testing_audit FOR SELECT TO authenticated USING(public.testing_owner());
CREATE POLICY records_read ON public.test_records FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.account_session_active()); CREATE POLICY records_insert ON public.test_records FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.account_session_active()); CREATE POLICY records_delete ON public.test_records FOR DELETE TO authenticated USING(user_id=auth.uid() AND public.account_session_active());
CREATE FUNCTION public.accept_testing_invitation(invite_token_hash text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE inv public.testing_invitations; verified_email text; BEGIN SELECT email INTO verified_email FROM auth.users WHERE id=auth.uid() AND email_confirmed_at IS NOT NULL; IF verified_email IS NULL THEN RAISE EXCEPTION 'Verified identity required'; END IF; SELECT * INTO inv FROM public.testing_invitations WHERE token_hash=invite_token_hash FOR UPDATE; IF inv.id IS NULL OR inv.revoked_at IS NOT NULL OR inv.accepted_at IS NOT NULL OR inv.expires_at<=now() OR lower(inv.email)<>lower(verified_email) THEN RAISE EXCEPTION 'Invitation unavailable'; END IF; IF NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=inv.created_by AND active AND (role='owner' OR can_invite)) THEN RAISE EXCEPTION 'Invitation unavailable'; END IF; IF EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid()) THEN RAISE EXCEPTION 'Already enrolled or revoked'; END IF; INSERT INTO public.user_roles(user_id,role) VALUES(auth.uid(),inv.role); UPDATE public.testing_invitations SET accepted_at=now() WHERE id=inv.id; INSERT INTO public.testing_audit(actor_id,event,subject_id) VALUES(auth.uid(),'invite_accepted',inv.id); END $$; REVOKE ALL ON FUNCTION public.accept_testing_invitation(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.accept_testing_invitation(text) TO authenticated;
CREATE FUNCTION public.manage_testing_member(target_user uuid, new_role text, invite_permission boolean, is_active boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN IF NOT public.testing_owner() OR new_role NOT IN ('admin','member') THEN RAISE EXCEPTION 'Owner required'; END IF; UPDATE public.user_roles SET role=new_role,can_invite=invite_permission,active=is_active WHERE user_id=target_user AND role<>'owner'; IF NOT FOUND THEN RAISE EXCEPTION 'Member unavailable'; END IF; IF NOT is_active THEN UPDATE public.account_sessions SET revoked_at=now() WHERE user_id=target_user AND revoked_at IS NULL; END IF; INSERT INTO public.testing_audit(actor_id,event,subject_id) VALUES(auth.uid(),'membership_updated',target_user); END $$; REVOKE ALL ON FUNCTION public.manage_testing_member(uuid,text,boolean,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.manage_testing_member(uuid,text,boolean,boolean) TO authenticated;
CREATE FUNCTION public.revoke_testing_invitation(target_invite uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN IF NOT public.testing_inviter() THEN RAISE EXCEPTION 'Invite permission required'; END IF; UPDATE public.testing_invitations SET revoked_at=now() WHERE id=target_invite AND accepted_at IS NULL AND revoked_at IS NULL AND (created_by=auth.uid() OR public.testing_owner()); IF FOUND THEN INSERT INTO public.testing_audit(actor_id,event,subject_id) VALUES(auth.uid(),'invite_revoked',target_invite); END IF; END $$; REVOKE ALL ON FUNCTION public.revoke_testing_invitation(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.revoke_testing_invitation(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.register_account_session() RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE sid uuid:=nullif(auth.jwt()->>'session_id','')::uuid; uid uuid:=auth.uid(); BEGIN IF NOT public.testing_member() OR uid IS NULL OR sid IS NULL OR NOT EXISTS(SELECT 1 FROM auth.sessions WHERE id=sid AND user_id=uid) THEN RAISE EXCEPTION 'Invitation-only access required'; END IF; IF EXISTS(SELECT 1 FROM public.account_sessions WHERE id=sid AND (revoked_at IS NOT NULL OR expires_at<=now())) THEN RAISE EXCEPTION 'Session expired or revoked'; END IF; IF NOT EXISTS(SELECT 1 FROM public.account_sessions WHERE id=sid) THEN INSERT INTO public.account_sessions(id,user_id) VALUES(sid,uid); INSERT INTO public.account_activity(user_id,event) VALUES(uid,'session_registered'); ELSE UPDATE public.account_sessions SET last_seen_at=now() WHERE id=sid AND user_id=uid; END IF; RETURN sid; END $$;